     2→
     3→const MAX_TURNS = 50;
     4→const DONE_MARKER = 'TASK_COMPLETE';
     5→
     6→/**
     7→ * Echo agent — agentic loop that sends task instructions to the LLM,
     8→ * follows the LLM's lead on tool use, and terminates when the LLM
     9→ * signals completion or the turn limit is reached.
    10→ *
    11→ * The same agent works for simple tasks (completes in 1–3 turns) and
    12→ * looping tasks (the task instructions cause the LLM to repeat itself,
    13→ * triggering the loop detector middleware).
    14→ */
    15→export const agent: AgentFn = async (llmCall, tools) => {
    16→  const messages: LlmMessage[] = [
    17→    {
    18→      role: 'system',
    19→      content: [
    20→        'You are a task-completion agent running inside a sandbox.',
    21→        'You have access to a filesystem. The human will relay tool results back to you.',
    22→        'When you want to write a file, output a line: WRITE_FILE:<path>:<content>',
    23→        'When you want to run a shell command, output a line: EXEC:<command>',
    24→        `When the task is fully done, include the marker "${DONE_MARKER}" in your response.`,
    25→        'Be concise. Complete the task as described.',
    26→      ].join('\n'),
    27→    },
    28→    {
    29→      role: 'user',
    30→      content: 'Here is your task. Follow the instructions exactly.',
    31→    },
    32→  ];
    33→
    34→  let lastResponse = '';
    35→  const writtenFiles: string[] = [];
    36→
    37→  for (let turn = 0; turn < MAX_TURNS; turn++) {
    38→    const response = await llmCall(messages);
    39→    lastResponse = response.content;
    40→
    41→    // Append assistant response to conversation
    42→    messages.push({ role: 'assistant', content: response.content });
    43→
    44→    // Parse and execute tool actions from the response
    45→    const toolResults: string[] = [];
    46→
    47→    for (const line of response.content.split('\n')) {
    48→      const writeMatch = line.match(/^WRITE_FILE:([^:]+):(.+)$/);
    49→      if (writeMatch) {
    50→        const filePath = writeMatch[1]!;
    51→        const content = writeMatch[2]!;
    52→        await tools.writeFile(filePath, content);
    53→        writtenFiles.push(filePath);
    54→        toolResults.push(`Wrote file: ${filePath}`);
    55→      }
    56→
    57→      const execMatch = line.match(/^EXEC:(.+)$/);
    58→      if (execMatch) {
    59→        const cmd = execMatch[1]!;
    60→        const result = await tools.exec(cmd);
    61→        toolResults.push(
    62→          `Exec [exit=${result.exitCode}]: ${result.stdout}${result.stderr ? `\nstderr: ${result.stderr}` : ''}`,
    63→        );
    64→      }
    65→    }
    66→
    67→    // Check for completion marker
    68→    if (response.content.includes(DONE_MARKER)) {
    69→      return {
    70→        finalMessage: lastResponse,
    71→        artifacts: writtenFiles.length > 0 ? writtenFiles : undefined,
    72→      };
    73→    }
    74→
    75→    // Feed tool results back (or prompt to continue)
    76→    if (toolResults.length > 0) {
    77→      messages.push({ role: 'user', content: toolResults.join('\n') });
    78→    } else {
    79→      messages.push({ role: 'user', content: 'Continue with the task.' });
    80→    }
    81→  }
    82→
    83→  // Turn limit reached without explicit completion
    84→  return {
    85→    finalMessage: lastResponse,
    86→    artifacts: writtenFiles.length > 0 ? writtenFiles : undefined,
    87→  };
    88→};
    89→'}]}

