    20→  tracer: RunTracer;
    21→  getTokenCount: () => number;
    22→  runConfig: RunConfig;
    23→  startedAt: Date;
    24→}
    25→
    26→/**
    27→ * Empty manifest used when artifact flush fails — teardown must not abort.
    28→ */
    29→function emptyManifest(runId: string): ArtifactManifest {
    30→  return {
    31→    outputDir: path.join('runs', runId, 'artifacts'),
    32→    files: [],
    33→  };
    34→}
    35→
    36→/**
    37→ * Single convergent teardown path for all kill reasons (budget, loop, TTL,
    38→ * clean completion). All kill paths MUST call this function.
    39→ *
    40→ * Execution order (guaranteed):
    41→ *   1. Log KillEvent JSON to stdout
    42→ *   2. flushArtifacts(runId) — download sandbox artifacts to host
    43→ *   3. tracer.close(killReason, tokenCount) — close Langfuse trace and flush
    44→ *   4. sandboxRunner.destroy() — destroy E2B sandbox
    45→ *   5. Write RunResult JSON to ./runs/<runId>/result.json
    46→ *
    47→ * Each step is wrapped in try/catch. If any step fails, the error is logged
    48→ * and execution continues to the next step. Teardown NEVER throws.
    49→ *
    50→ * Idempotent: a boolean guard prevents the sequence from executing more than
    51→ * once per teardown call site. Re-entrant calls return immediately.
    52→ */
    53→export async function teardown(
    54→  context: TeardownContext,
    55→  killReason: KillReason,
    56→): Promise<void> {
    57→  const { sandboxRunner, tracer, getTokenCount, runConfig, startedAt } =
    58→    context;
    59→
    60→  const runId = tracer.getRunId();
    61→  const tokenCount = getTokenCount();
    62→  const completedAt = new Date();
    63→  const wallTimeMs = completedAt.getTime() - startedAt.getTime();
    64→
    65→  // ── Step 1: Log KillEvent JSON to stdout ──────────────────────────────────
    66→  const killEvent: KillEvent = {
    67→    runId,
    68→    killReason,
    69→    tokenCount,
    70→    wallTimeMs,
    71→    timestamp: completedAt.toISOString(),
    72→  };
    73→
    74→  try {
    75→    console.log(JSON.stringify(killEvent));
    76→  } catch (err) {
    77→    console.error(
    78→      JSON.stringify({
    79→        event: 'teardown_step_failed',
    80→        step: 'log_kill_event',
    81→        runId,
    82→        error: err instanceof Error ? err.message : String(err),
    83→        timestamp: new Date().toISOString(),
    84→      }),
    85→    );
    86→  }
    87→
    88→  // ── Step 2: Flush artifacts from sandbox to host ───────────────────────────
    89→  let artifactManifest: ArtifactManifest = emptyManifest(runId);
    90→
    91→  try {
    92→    artifactManifest = await sandboxRunner.flushArtifacts(runId);
    93→  } catch (err) {
    94→    console.error(
    95→      JSON.stringify({
    96→        event: 'teardown_step_failed',
    97→        step: 'flush_artifacts',
    98→        runId,
    99→        error: err instanceof Error ? err.message : String(err),
   100→        timestamp: new Date().toISOString(),
   101→      }),
   102→    );
   103→  }
   104→
   105→  // ── Step 3: Close Langfuse trace and flush ────────────────────────────────
   106→  try {
   107→    await tracer.close(killReason, tokenCount);
   108→  } catch (err) {
   109→    console.error(
   110→      JSON.stringify({
   111→        event: 'teardown_step_failed',
   112→        step: 'tracer_close',
   113→        runId,
   114→        error: err instanceof Error ? err.message : String(err),
   115→        timestamp: new Date().toISOString(),
   116→      }),
   117→    );
   118→  }
   119→
   120→  // ── Step 4: Destroy E2B sandbox ───────────────────────────────────────────
   121→  try {
   122→    await sandboxRunner.destroy();
   123→  } catch (err) {
   124→    console.error(
   125→      JSON.stringify({
   126→        event: 'teardown_step_failed',
   127→        step: 'sandbox_destroy',
   128→        runId,
   129→        error: err instanceof Error ? err.message : String(err),
